CREATE TABLE cpf_sftp_transfer (
 transfer_no NUMBER(19) GENERATED BY DEFAULT AS IDENTITY, transfer_id VARCHAR2(64) NOT NULL, operation_code VARCHAR2(32) NOT NULL, source_path VARCHAR2(1000), target_path VARCHAR2(1000), transfer_status VARCHAR2(32) NOT NULL, byte_count NUMBER(19) DEFAULT 0 NOT NULL, checksum_value VARCHAR2(128), transaction_id VARCHAR2(64), detail VARCHAR2(2000), started_at TIMESTAMP NOT NULL, completed_at TIMESTAMP, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, CONSTRAINT pk_cpf_sftp_transfer PRIMARY KEY(transfer_no), CONSTRAINT uk_cpf_sftp_transfer_id UNIQUE(transfer_id));
CREATE INDEX ix_cpf_sftp_transfer_status ON cpf_sftp_transfer(transfer_status,started_at);
